CREATE TABLE `orderitem` (
  `Id` bigint NOT NULL AUTO_INCREMENT,
  `CustomerOrderId` bigint NOT NULL,
  `ProductId` bigint NOT NULL,
  `OrderItemStatusId` bigint NOT NULL,
  `EmployeeId` bigint DEFAULT NULL,
  `Quantity` decimal(18,3) NOT NULL,
  `UnitPrice` decimal(18,2) NOT NULL,
  `DiscountAmount` decimal(18,2) NOT NULL DEFAULT '0.00',
  `TotalAmount` decimal(18,2) NOT NULL,
  `Notes` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `PizzaSizeId` bigint DEFAULT NULL,
  `PizzaCrustId` bigint DEFAULT NULL,
  `PizzaEdgeId` bigint DEFAULT NULL,
  `SentToKitchenAt` datetime(6) DEFAULT NULL,
